import { NextRequest } from 'next/server';
import { TABLE_REGISTRY } from '@/lib/tableRegistry';
import { dataGet, dataPost, dataPatch, dataDelete, dataNotFound } from '@/lib/dataRoute';

/* Crm domain data route (GENERATED by the wire closure, 2026-11-15):
   the named API surface for the crm tables that had no hand-written
   route. Tenant-scoped CRUD through the shared handler in
   lib/dataRoute.ts, driven by each table's TABLE_REGISTRY entry.
   Tables served here:
   - crm_appointment_services
   - crm_audit_log
   - crm_automation_enrollments
   - crm_automation_runs
   - crm_campaign_members
   - crm_commission_entries
   - crm_commission_plans
   - crm_commission_rules
   - crm_commission_tiers
   - crm_communication_preferences
   - crm_customer_behavior
   - crm_customer_contact_methods
   - crm_customer_preferences
   - crm_customer_tag_assignments
   - crm_customer_tags
   - crm_document_versions
   - crm_external_identities
   - crm_funnel_events
   - crm_holiday_blackouts
   - crm_idempotency_keys
   - crm_merge_log
   - crm_operating_hours
   - crm_party_dependents
   - crm_permanent_alerts
   - crm_pricing_rules
   - crm_product_recommendations
   - crm_record_parties
   - crm_record_types
   - crm_saved_views
   - crm_search_index
   - crm_service_location_availability
   - crm_service_package_items
   - crm_service_packages
   - crm_settings
   - crm_staff_commission_assignments
   - crm_staff_documents
   - crm_staff_incident_reports
   - crm_staff_performance_notes
   - crm_staff_shifts
   - crm_staff_time_clock_entries
   - crm_staff_training_records
   - crm_surcharges
   - crm_task_comments
   - crm_v_sales_tracking
*/

const SERVED = new Set([
  'crm_appointment_services',
  'crm_audit_log',
  'crm_automation_enrollments',
  'crm_automation_runs',
  'crm_campaign_members',
  'crm_commission_entries',
  'crm_commission_plans',
  'crm_commission_rules',
  'crm_commission_tiers',
  'crm_communication_preferences',
  'crm_customer_behavior',
  'crm_customer_contact_methods',
  'crm_customer_preferences',
  'crm_customer_tag_assignments',
  'crm_customer_tags',
  'crm_document_versions',
  'crm_external_identities',
  'crm_funnel_events',
  'crm_holiday_blackouts',
  'crm_idempotency_keys',
  'crm_merge_log',
  'crm_operating_hours',
  'crm_party_dependents',
  'crm_permanent_alerts',
  'crm_pricing_rules',
  'crm_product_recommendations',
  'crm_record_parties',
  'crm_record_types',
  'crm_saved_views',
  'crm_search_index',
  'crm_service_location_availability',
  'crm_service_package_items',
  'crm_service_packages',
  'crm_settings',
  'crm_staff_commission_assignments',
  'crm_staff_documents',
  'crm_staff_incident_reports',
  'crm_staff_performance_notes',
  'crm_staff_shifts',
  'crm_staff_time_clock_entries',
  'crm_staff_training_records',
  'crm_surcharges',
  'crm_task_comments',
  'crm_v_sales_tracking'
]);

function entry(table: string) {
  return SERVED.has(table) ? TABLE_REGISTRY[table] ?? null : null;
}

export async function GET(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataGet(req, table, r) : dataNotFound(table);
}

export async function POST(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataPost(req, table, r) : dataNotFound(table);
}

export async function PATCH(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataPatch(req, table, r) : dataNotFound(table);
}

export async function DELETE(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataDelete(req, table, r) : dataNotFound(table);
}
